// TH15 v1.00b Stage 5 mid-stage wave (th15_s5_w03).
// Source: st05.ecl.txt MainSub02:1487-1502 + MainSub02b:1504-1526,
//         GirlD01:872-894/GirlD01_at:896-923, GirlA03:262-271/GirlA03_at:273-288/GirlA03_at2:290-330.
// Card frame 0 = MainSub02 schedule start; OPENING_BUFFER is prepended by the shell.

const TIME_LIMIT: int = 2224;
const OPENING_BUFFER: int = 120;

const GIRL_D01_SHAPE: int = 656;  // src type 19 (TH15_BIG_BALL2), color 3
const GIRL_A03_SHAPE: int = 720;  // src type 23 (TH15_BIG_STAR_R), color 1
const LASER_COLOR: int = 6;       // src EX LASER c=6 (sprite 38 has no target equivalent)
const LASER_STARTUP: int = 60;
const LASER_ACTIVE: int = 150;    // src expand 30 + hold 120 (constant-width approximation)
const LASER_FADE: int = 30;

// src GirlD01_at EX: ANIM -> WAIT 30 -> LASER (infinite, angle 90deg, length 512, width 16,
// phases 60/30/120/30), LASER d bit16 deletes the parent bullet.
// ANIM spawn stage omitted per approved policy; its -4*velocity offset is kept at fire time.
xformdef D01_BULLET_END {
    wait(30);
    set_life(1);
}

// src GirlA03_at2 EX VELTIME 0x200000: a=120, r=2.0/4.0/4.4/5.0, s keeps angle.
// Scalar speed ramps 0.5 -> r over 120 frames along the spawn angle.
xformdef A03_VELTIME(delta: fx) {
    set_accel(delta);
    wait(120);
    set_accel(0fx);
}

async sub d01_bullet_to_laser() {
    // xform life and fire-task start are 1 frame apart: wait life-1.
    wait(29);
    _ = laser(LASER_COLOR, $self_x, $self_y, 90deg, 460.8fx, 8fx,
              LASER_STARTUP, LASER_ACTIVE, LASER_FADE);
}

// src GirlD01():269-288 main body (anm/drop omitted).
async sub girl_d01() {
    set_invuln(65535);
    set_hurtbox(16fx);   // src setHurtbox(32,32)
    set_hitbox(12fx);    // src setHitbox(24,24)
    move_vel(0, 90deg, 2.7fx, EASE_LINEAR);
    move_speed(60, 0fx, EASE_QUAD_IN);   // src moveSpeedTime(60,1,0.0)
    spawn girl_d01_fire();
    wait(120);
    move_speed(80, 1fx, EASE_QUAD_IN);   // src moveSpeedTime(80,1,1.0)
    wait(60);
    loop { wait(1); }
}

// src GirlD01_at():896-923. Fan mode 1 around 90deg, spread A shrinks 15deg per volley;
// 2 balls per volley, speed 1.0, volleys E/N/H/L = 2/4/5/6.
async sub girl_d01_fire() {
    var rank: int = global(GVAR_RANK);
    var volleys: int = 4;
    if rank == RANK_EASY {
        volleys = 2;
    } else if rank == RANK_HARD {
        volleys = 5;
    } else if rank == RANK_LUNATIC {
        volleys = 6;
    }
    var spread: int = 16384;   // A = 90deg in BAM (src %A = 1.570796)
    wait(10);
    for i in 0..volleys {
        var hi: angle = (16384 + spread / 2) as angle;
        var lo: angle = (16384 - spread / 2) as angle;
        _ = fire(GIRL_D01_SHAPE, 3, $self_x - 4fx * cos(hi), $self_y - 4fx * sin(hi),
                 1fx, hi, D01_BULLET_END, d01_bullet_to_laser);
        _ = fire(GIRL_D01_SHAPE, 3, $self_x - 4fx * cos(lo), $self_y - 4fx * sin(lo),
                 1fx, lo, D01_BULLET_END, d01_bullet_to_laser);
        spread = spread - 2731;   // src %A -= 0.261799 rad (15deg)
        wait(10);
    }
}

// src GirlA03_at():273-288. Movement lives in the main task because the source
// async attack must outlive GirlA03()'s delete().
async sub girl_a03(ang: angle, mirrored: int) {
    set_invuln(65535);
    set_hurtbox(12fx);   // src setHurtbox(24,24)
    set_hitbox(8fx);     // src setHitbox(16,16)
    var a0: angle = ang;
    var a1: angle = -11.25deg;   // src moveVelTime(120,1,-0.19634955,2.0)
    var a2: angle = 135deg;      // src moveVelTime(60,4,2.3561945,4.0)
    if mirrored != 0 {
        // enmCreateM: source mirror flips the horizontal axis -> angle 180deg - a.
        a0 = (32768 - (ang as int)) as angle;
        a1 = 34816bam;
        a2 = 8192bam;
    }
    spawn girl_a03_fire();
    move_vel(0, a0, 3fx, EASE_LINEAR);
    move_vel(120, a1, 2fx, EASE_QUAD_IN);
    wait(120);
    move_vel(60, a2, 4fx, EASE_QUAD_OUT);
    loop { wait(1); }
}

// src GirlA03_at2():290-330. Aimed single shot, ANIM -2px spawn offset kept,
// VELTIME ramp; shots/wait E/N/H/L = 1/10/10/10 and 37/37/30/20.
async sub girl_a03_fire() {
    var rank: int = global(GVAR_RANK);
    var shots: int = 10;
    var gap: int = 20;
    var delta: fx = 0.0375fx;    // (5.0 - 0.5) / 120
    if rank == RANK_EASY {
        shots = 1;
        gap = 37;
        delta = 0.0125fx;        // (2.0 - 0.5) / 120
    } else if rank == RANK_NORMAL {
        gap = 37;
        delta = 0.0291667fx;     // (4.0 - 0.5) / 120
    } else if rank == RANK_HARD {
        gap = 30;
        delta = 0.0325fx;        // (4.4 - 0.5) / 120
    }
    wait(39);
    for i in 0..shots {
        var a: angle = aim_player();
        _ = fire(GIRL_A03_SHAPE, 1, $self_x - 2fx * cos(a), $self_y - 2fx * sin(a),
                 0.5fx, a, A03_VELTIME(delta), none);
        wait(gap);
    }
}

// src MainSub02b():1504-1526. F0 = 22.5deg +- 20deg shared by the pair;
// left/right y each draw their own RANDF2; pairs E=25 every 40, else 50 every 20.
async sub main_sub02b() {
    var rank: int = global(GVAR_RANK);
    var pairs: int = 50;
    var gap: int = 20;
    if rank == RANK_EASY {
        pairs = 25;
        gap = 40;
    }
    for i in 0..pairs {
        var r: int = rand(65536) - 32768;
        var ang: angle = (4096 + (r * 3641) / 32768) as angle;
        var u1: fx = (rand(65536) - 32768) as fx / 32768;
        var u2: fx = (rand(65536) - 32768) as fx / 32768;
        var y1: fx = 64fx + 32fx * u1;
        var y2: fx = 64fx + 32fx * u2;
        _ = spawn_enemy(-224fx, y1, 50, 0, 0, 0, girl_a03(ang, 0));
        _ = spawn_enemy(224fx, y2, 50, 0, 0, 0, girl_a03(ang, 1));
        wait(gap);
    }
}

// src MainSub02():1487-1502 schedule; card frame 120 = source frame 0.
async sub pattern() {
    wait(OPENING_BUFFER);
    wait(160);
    _ = spawn_enemy(0fx, -48fx, 800, 0, 0, 0, girl_d01);
    wait(50);
    spawn main_sub02b();
    wait(270);
    _ = spawn_enemy(120fx, -48fx, 800, 0, 0, 0, girl_d01);
    wait(230);
    _ = spawn_enemy(0fx, -48fx, 800, 0, 0, 0, girl_d01);
    wait(230);
    _ = spawn_enemy(130fx, -48fx, 600, 0, 0, 0, girl_d01);
    _ = spawn_enemy(-130fx, -48fx, 600, 0, 0, 0, girl_d01);
    wait(380);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
